-- Seed data for public.sign_interpretations.
-- 12 signs x 3 points (sun, moon, rising) x 2 locales (vi, en) = 72 rows.
-- Static free-tier Big-Three texts; authored offline, never AI-generated at runtime.

insert into public.sign_interpretations (sign, point, locale, content) values
-- ============================================================ aries
('aries', 'sun', 'vi', 'Mặt Trời Bạch Dương cho bạn một trái tim dũng cảm và một nguồn năng lượng hiếm ai theo kịp. Bạn sinh ra để khởi đầu: một dự án mới, một con đường chưa ai đi, một quyết định mà người khác còn chần chừ. Sự thẳng thắn của bạn đôi khi khiến người xung quanh bất ngờ, nhưng cũng chính nó làm họ tin tưởng bạn. Hãy nhớ rằng ngọn lửa của bạn cháy sáng nhất khi có một mục tiêu xứng đáng để theo đuổi.'),
('aries', 'sun', 'en', 'With the Sun in Aries, courage sits at the very center of who you are. You are a natural initiator, happiest when you are the first one through the door, starting what others only talk about. Your directness can catch people off guard, yet it is exactly what makes them trust you. Give that inner fire a goal worth chasing and it becomes unstoppable.'),
('aries', 'moon', 'vi', 'Mặt Trăng Bạch Dương khiến cảm xúc của bạn đến nhanh và mãnh liệt như một cơn gió lớn. Bạn cần được tự do bày tỏ ngay khi trái tim lên tiếng, thay vì kìm nén chờ thời điểm hoàn hảo. Tin vui là bạn cũng nguôi rất nhanh và hiếm khi giữ hờn giận lâu. Học cách dừng lại một nhịp trước khi phản ứng sẽ giúp bạn giữ được cả sự chân thật lẫn những mối quan hệ quý giá.'),
('aries', 'moon', 'en', 'An Aries Moon feels everything fast and at full volume. Your inner world needs room to express itself the moment emotion strikes, not hours later when the moment has passed. The gift is that storms pass quickly for you, and you rarely hold a grudge. Learning to take one breath before reacting lets you keep both your honesty and the people you love.'),
('aries', 'rising', 'vi', 'Với cung Mọc Bạch Dương, bạn bước vào phòng như một tia lửa: nhanh, rõ ràng và đầy sức sống. Người mới gặp thường ấn tượng bởi sự tự tin và cách bạn đi thẳng vào vấn đề. Vẻ ngoài quyết đoán ấy giúp bạn dễ được giao vai trò dẫn dắt, dù bên trong đôi khi bạn cũng hồi hộp như ai. Cứ giữ nguyên nguồn năng lượng ấy, nó là lời giới thiệu đẹp nhất của bạn.'),
('aries', 'rising', 'en', 'With Aries rising, you enter a room like a spark: quick, bright and impossible to miss. New people read you as confident and refreshingly direct, someone who gets straight to the point. That bold first impression often lands you in leadership roles, even on days when you feel nervous inside. Keep that energy; it is the best introduction you could ask for.'),

-- ============================================================ taurus
('taurus', 'sun', 'vi', 'Mặt Trời Kim Ngưu tặng bạn sự vững chãi mà nhiều người ao ước. Bạn xây dựng cuộc sống từng viên gạch một, kiên nhẫn và chắc chắn, không để những cơn sóng nhất thời cuốn đi. Bạn biết trân trọng những điều đẹp đẽ giản dị: một bữa ăn ngon, một buổi chiều yên tĩnh, một lời hứa được giữ trọn. Chính sự bền bỉ ấy khiến những gì bạn tạo ra thường tồn tại rất lâu.'),
('taurus', 'sun', 'en', 'A Taurus Sun gives you a steadiness that others quietly envy. You build your life brick by patient brick, refusing to be swept away by every passing trend. You have a real gift for savoring simple pleasures: good food, quiet afternoons, promises that are actually kept. What you create tends to last, because you never rush the foundation.'),
('taurus', 'moon', 'vi', 'Mặt Trăng Kim Ngưu cần sự an toàn và những nhịp điệu quen thuộc để trái tim được nghỉ ngơi. Bạn tìm thấy bình yên trong những điều chạm được: một căn bếp ấm, một cái ôm chặt, một thói quen nhỏ mỗi tối. Cảm xúc của bạn sâu và bền, một khi đã thương ai thì thương rất lâu. Chỉ cần nhớ rằng thay đổi không phải lúc nào cũng là mối đe dọa, đôi khi nó là món quà.'),
('taurus', 'moon', 'en', 'A Taurus Moon finds emotional peace in comfort, routine and things you can actually touch: a warm kitchen, a long hug, the same quiet ritual every evening. Your feelings run deep and steady, and when you love someone, you love them for the long haul. Security is not a luxury for you; it is how your heart recharges. Just remember that change is not always a threat — sometimes it arrives carrying a gift.'),
('taurus', 'rising', 'vi', 'Cung Mọc Kim Ngưu cho bạn một sự hiện diện điềm tĩnh khiến người khác thấy an tâm ngay từ lần đầu gặp. Bạn thường được nhận xét là đáng tin, chân thành và có gu thẩm mỹ tinh tế. Bạn không cần nói nhiều để gây ấn tượng; chính sự vững vàng của bạn đã tự lên tiếng. Trong một thế giới vội vã, phong thái từ tốn của bạn là điều hiếm có và đáng quý.'),
('taurus', 'rising', 'en', 'Taurus rising wraps you in a calm, grounded presence that puts people at ease the moment you arrive. Others tend to describe you as dependable, genuine and quietly stylish. You do not need to talk much to make an impression; your steadiness speaks for itself. In a world that rushes, your unhurried manner is rare and deeply reassuring.'),

-- ============================================================ gemini
('gemini', 'sun', 'vi', 'Mặt Trời Song Tử ban cho bạn một trí óc không bao giờ ngừng tò mò. Bạn học nhanh, nói chuyện duyên dáng và có khả năng kết nối những ý tưởng tưởng chừng chẳng liên quan. Với bạn, cuộc sống là một cuộc trò chuyện dài đầy thú vị, và bạn luôn muốn nghe thêm một câu chuyện nữa. Sự linh hoạt ấy là siêu năng lực của bạn, miễn là bạn cho phép mình đi sâu vào những gì thật sự quan trọng.'),
('gemini', 'sun', 'en', 'A Gemini Sun blesses you with a mind that never stops asking questions. You learn fast, converse effortlessly, and connect ideas that seem unrelated until you explain them. Life, to you, is one long fascinating conversation, and you always want one more story. That versatility is your superpower, especially when you let yourself go deep on the things that truly matter.'),
('gemini', 'moon', 'vi', 'Mặt Trăng Song Tử xử lý cảm xúc bằng ngôn từ: bạn cần nói ra, viết ra, hoặc kể cho ai đó nghe thì lòng mới nhẹ. Tâm trạng của bạn thay đổi nhanh, như những trang sách được lật liên tục, và điều đó hoàn toàn bình thường. Bạn cảm thấy được yêu thương nhất khi có người thật sự lắng nghe mình. Đừng quên rằng đôi khi trái tim cũng cần được cảm nhận, chứ không chỉ được phân tích.'),
('gemini', 'moon', 'en', 'A Gemini Moon processes feelings through words: you need to say it, write it, or tell someone before your heart feels lighter. Your moods can shift like pages turning, and that is simply how you are wired. You feel most loved when someone truly listens to you. Just remember that some emotions want to be felt, not only explained.'),
('gemini', 'rising', 'vi', 'Cung Mọc Song Tử khiến bạn xuất hiện với vẻ nhanh nhẹn, hóm hỉnh và đầy sức sống. Người mới gặp thường bị cuốn vào câu chuyện của bạn lúc nào không hay, bởi bạn có tài khiến mọi cuộc trò chuyện trở nên sống động. Ánh mắt tinh anh và sự tò mò chân thành của bạn là tấm thiệp chào tuyệt vời. Mọi người rời khỏi cuộc gặp với bạn thường mang theo một nụ cười.'),
('gemini', 'rising', 'en', 'With Gemini rising, you come across as quick, witty and wide awake to the world. Strangers find themselves pulled into conversation with you before they realize it, because you make every exchange feel alive. Your bright eyes and genuine curiosity are the warmest of welcome cards. People tend to walk away from meeting you with a smile they did not plan on.'),

-- ============================================================ cancer
('cancer', 'sun', 'vi', 'Mặt Trời Cự Giải đặt vào bạn một trái tim biết chăm sóc và che chở. Bạn cảm nhận được điều người khác cần trước cả khi họ nói ra, và bạn xây tổ ấm ở bất cứ nơi nào mình đến. Ký ức, gia đình và những người thân yêu là kho báu bạn gìn giữ cẩn thận nhất. Sự dịu dàng của bạn không phải là điểm yếu; nó là một dạng sức mạnh mà thế giới này luôn thiếu.'),
('cancer', 'sun', 'en', 'A Cancer Sun gives you a heart built for caring and protecting. You sense what people need before they say a word, and you create a sense of home wherever you go. Memories, family and your inner circle are the treasures you guard most carefully. Your tenderness is not a weakness; it is a kind of strength the world never has enough of.'),
('cancer', 'moon', 'vi', 'Mặt Trăng Cự Giải là vị trí mà Mặt Trăng cảm thấy như ở nhà, nên đời sống cảm xúc của bạn vô cùng phong phú và sâu sắc. Bạn cần một nơi trú ẩn an toàn, cả về vật chất lẫn tinh thần, để có thể là chính mình trọn vẹn. Trực giác của bạn về con người gần như không bao giờ sai. Hãy nhớ chăm sóc bản thân chu đáo như cách bạn vẫn chăm sóc mọi người.'),
('cancer', 'moon', 'en', 'The Moon is at home in Cancer, which makes your emotional life rich, deep and finely tuned. You need a safe harbor, both physical and emotional, to be fully yourself. Your intuition about people is almost never wrong. Make sure you care for yourself with the same devotion you so freely offer everyone else.'),
('cancer', 'rising', 'vi', 'Cung Mọc Cự Giải cho bạn một vẻ ngoài dịu dàng, dễ gần và có chút gì đó khiến người khác muốn tâm sự. Ngay lần đầu gặp, mọi người thường cảm thấy được lắng nghe và được quan tâm thật lòng. Bạn có thể hơi dè dặt lúc ban đầu, như con sóng thăm dò bờ cát, nhưng khi đã tin tưởng thì vô cùng ấm áp. Chính sự chân thành ấy khiến ấn tượng về bạn ở lại rất lâu.'),
('cancer', 'rising', 'en', 'Cancer rising gives you a gentle, approachable aura that makes people want to confide in you. Even at a first meeting, others feel genuinely heard and cared for in your presence. You may start out a little reserved, testing the waters, but once trust is built your warmth pours out. That sincerity is why first impressions of you tend to linger for years.'),

-- ============================================================ leo
('leo', 'sun', 'vi', 'Mặt Trời Sư Tử ở đúng cung của mình, nên trong bạn có một ánh sáng tự nhiên không cần cố gắng tỏa ra. Bạn sống hào phóng, yêu hết mình và luôn muốn những người quanh mình cũng được tỏa sáng. Sự tự tin của bạn truyền cảm hứng, và lòng trung thành của bạn thì hiếm ai sánh được. Sân khấu lớn nhất của bạn chính là cuộc đời, hãy cứ bước lên đó bằng cả trái tim.'),
('leo', 'sun', 'en', 'The Sun rules Leo, so a natural light lives in you that never needs forcing. You love generously, give wholeheartedly, and genuinely want the people around you to shine too. Your confidence inspires others, and your loyalty is nearly impossible to match. Life itself is your stage; keep stepping onto it with your whole heart.'),
('leo', 'moon', 'vi', 'Mặt Trăng Sư Tử cần được nhìn nhận và trân trọng để trái tim thấy đủ đầy. Khi được yêu thương đúng cách, bạn đáp lại bằng một sự ấm áp rực rỡ hiếm có. Cảm xúc của bạn lớn và chân thật, bạn không giỏi giả vờ thờ ơ. Đừng ngại thừa nhận rằng mình cần những lời khen chân thành; đó không phải kiêu ngạo, đó là cách trái tim bạn được nuôi dưỡng.'),
('leo', 'moon', 'en', 'A Leo Moon needs to feel seen and appreciated for your heart to feel full. When you are loved well, you give back a radiant warmth few can match. Your emotions are big and honest; pretending not to care has never been your talent. Do not be ashamed of needing genuine praise — that is not vanity, it is simply how your heart is fed.'),
('leo', 'rising', 'vi', 'Cung Mọc Sư Tử khiến bạn khó mà đi vào đâu một cách lặng lẽ, ngay cả khi bạn muốn. Có điều gì đó trong phong thái của bạn, ấm áp và đường hoàng, tự nhiên thu hút ánh nhìn. Người mới gặp thường cảm nhận được sự rộng lượng và nguồn năng lượng tích cực bạn mang theo. Hãy tận hưởng điều đó; sự hiện diện của bạn thật sự làm căn phòng sáng hơn.'),
('leo', 'rising', 'en', 'With Leo rising, slipping into a room unnoticed is nearly impossible, even when you try. There is something in your bearing, warm and dignified, that naturally draws the eye. New acquaintances immediately pick up on your generosity and the bright energy you carry. Enjoy it; your presence genuinely makes a room lighter.'),

-- ============================================================ virgo
('virgo', 'sun', 'vi', 'Mặt Trời Xử Nữ cho bạn đôi mắt nhìn thấy những chi tiết mà người khác bỏ qua, và đôi tay luôn muốn làm mọi thứ tốt hơn. Bạn thể hiện tình cảm bằng hành động: sửa giúp một thứ hỏng, nhớ một điều nhỏ, chuẩn bị chu đáo trước khi ai kịp nhờ. Sự tận tâm của bạn là món quà thầm lặng nhưng vô giá. Chỉ cần nhớ rằng bạn xứng đáng với sự tử tế mà bạn dành cho công việc và mọi người.'),
('virgo', 'sun', 'en', 'A Virgo Sun gives you eyes that catch what everyone else misses, and hands that itch to make things better. You show love through action: fixing what is broken, remembering the small things, preparing before anyone thinks to ask. Your quiet devotion is a priceless gift. Just remember that you deserve the same kindness you pour into your work and your people.'),
('virgo', 'moon', 'vi', 'Mặt Trăng Xử Nữ tìm thấy bình yên khi mọi thứ đâu vào đấy: một kế hoạch rõ ràng, một góc nhà gọn gàng, một danh sách được gạch xong. Khi lo lắng, bạn có xu hướng phân tích cảm xúc thay vì cảm nhận chúng. Bạn chăm sóc người mình thương bằng những việc cụ thể, thiết thực và đầy tinh tế. Hãy cho phép bản thân được không hoàn hảo; trái tim bạn không cần đạt điểm mười.'),
('virgo', 'moon', 'en', 'A Virgo Moon finds calm when life is in order: a clear plan, a tidy corner, a list with everything crossed off. When anxiety rises, you tend to analyze your feelings instead of simply feeling them. You care for loved ones in concrete, practical, quietly thoughtful ways. Let yourself be imperfect sometimes; your heart was never meant to be graded.'),
('virgo', 'rising', 'vi', 'Cung Mọc Xử Nữ mang đến cho bạn vẻ ngoài chỉn chu, thông minh và đáng tin cậy. Người mới gặp thường ấn tượng bởi sự quan sát tinh tế và những câu hỏi sắc sảo của bạn. Bạn có thể hơi kín đáo lúc đầu, nhưng sự chân thành và hữu ích của bạn nhanh chóng chiếm được cảm tình. Trong mắt mọi người, bạn là người mà họ muốn có bên cạnh khi cần giải quyết vấn đề.'),
('virgo', 'rising', 'en', 'Virgo rising presents you to the world as polished, sharp and trustworthy. New people quickly notice how observant you are and how precise your questions can be. You may seem a little reserved at first, but your sincerity and helpfulness win people over fast. You are exactly the person others want beside them when something needs solving.'),

-- ============================================================ libra
('libra', 'sun', 'vi', 'Mặt Trời Thiên Bình cho bạn một tâm hồn yêu cái đẹp và một bản năng tìm kiếm sự công bằng. Bạn nhìn thấy mọi mặt của vấn đề, và tài ngoại giao của bạn thường là chiếc cầu nối giữa những người bất đồng. Các mối quan hệ với bạn không phải điều phụ, chúng là trung tâm của một cuộc sống ý nghĩa. Hãy nhớ rằng ý kiến của riêng bạn cũng xứng đáng có một ghế trong mọi cuộc thương lượng.'),
('libra', 'sun', 'en', 'A Libra Sun gives you a soul that loves beauty and an instinct for fairness. You see every side of a question, and your diplomacy often becomes the bridge between people who disagree. Relationships are not a side note for you; they sit at the center of a meaningful life. Just remember that your own opinion deserves a seat at every negotiation too.'),
('libra', 'moon', 'vi', 'Mặt Trăng Thiên Bình cần sự hài hòa để trái tim được yên: một không gian đẹp, một mối quan hệ êm ấm, một cuộc trò chuyện không gay gắt. Xung đột khiến bạn mệt mỏi hơn hầu hết mọi người, nên bạn thường là người chủ động làm lành. Bạn cảm thấy trọn vẹn nhất khi được sẻ chia cuộc sống với ai đó. Học cách nói ra điều mình thật sự muốn chính là món quà lớn nhất bạn tặng cho chính mình.'),
('libra', 'moon', 'en', 'A Libra Moon needs harmony the way others need air: a lovely space, a peaceful bond, a conversation free of sharp edges. Conflict drains you more than most, which is why you are so often the first to make peace. You feel most complete when life is shared with someone. Learning to say what you actually want is the greatest gift you can give yourself.'),
('libra', 'rising', 'vi', 'Cung Mọc Thiên Bình khoác lên bạn một vẻ duyên dáng tự nhiên khiến người đối diện lập tức thấy dễ chịu. Bạn thường được khen là lịch thiệp, tinh tế và biết cách khiến mọi người cảm thấy được tôn trọng. Nụ cười của bạn có khả năng làm dịu cả một căn phòng căng thẳng. Ấn tượng đầu tiên về bạn hầu như luôn là: một người mà ai cũng muốn quen.'),
('libra', 'rising', 'en', 'Libra rising drapes you in a natural charm that puts people instantly at ease. You are often described as gracious, tasteful and skilled at making everyone feel respected. Your smile can soften the tension in an entire room. The first impression you leave is almost always the same: someone worth knowing.'),

-- ============================================================ scorpio
('scorpio', 'sun', 'vi', 'Mặt Trời Bọ Cạp trao cho bạn chiều sâu và sức mạnh nội tâm hiếm có. Bạn không sống hời hợt: đã tin là tin trọn vẹn, đã làm là làm đến cùng. Bạn có khả năng đi qua những giai đoạn khó khăn và trở lại mạnh mẽ hơn, như thể tái sinh là một tài năng bẩm sinh. Sự chân thật mãnh liệt của bạn là điều khiến những người xứng đáng ở lại mãi bên bạn.'),
('scorpio', 'sun', 'en', 'A Scorpio Sun grants you rare depth and formidable inner strength. You do not do anything halfway: when you trust, you trust completely, and when you commit, you see it through. You have a remarkable ability to walk through hard seasons and emerge stronger, as if rebirth were a native talent. Your fierce honesty is exactly what makes the right people stay for life.'),
('scorpio', 'moon', 'vi', 'Mặt Trăng Bọ Cạp cảm nhận mọi thứ ở cường độ mà ít ai hiểu thấu. Bạn cần sự tin tưởng tuyệt đối mới mở lòng, và một khi đã mở thì đó là sự gắn bó sâu sắc hiếm có. Trực giác của bạn đọc được những điều người khác cố giấu. Hãy nhớ rằng để ai đó nhìn thấy sự mềm yếu của mình không phải là thua cuộc, đó là sự can đảm ở dạng tinh khiết nhất.'),
('scorpio', 'moon', 'en', 'A Scorpio Moon feels at an intensity few people ever understand. You need absolute trust before you open up, and when you do, the bond you form runs deeper than most people thought possible. Your intuition reads what others try hardest to hide. Remember that letting someone see your softness is not defeat — it is courage in its purest form.'),
('scorpio', 'rising', 'vi', 'Cung Mọc Bọ Cạp cho bạn một sự hiện diện cuốn hút và khó quên. Ánh mắt của bạn như nhìn thấu, khiến người mới gặp vừa tò mò vừa nể phục. Bạn không phô bày bản thân dễ dàng, và chính sự bí ẩn ấy làm nên sức hút riêng. Mọi người có thể chưa hiểu bạn ngay, nhưng chắc chắn họ sẽ không quên bạn.'),
('scorpio', 'rising', 'en', 'Scorpio rising gives you a magnetic, unforgettable presence. Your gaze seems to see straight through people, leaving new acquaintances curious and a little in awe. You reveal yourself slowly, and that air of mystery is precisely your allure. People may not figure you out at first meeting, but they will certainly never forget you.'),

-- ============================================================ sagittarius
('sagittarius', 'sun', 'vi', 'Mặt Trời Nhân Mã thắp trong bạn khát khao khám phá không bao giờ tắt. Bạn tin cuộc đời là một chuyến phiêu lưu lớn, và mỗi chân trời mới là một bài học đáng giá. Sự lạc quan của bạn có sức lây lan kỳ lạ, kéo mọi người ra khỏi những ngày u ám. Bạn nói thật, sống thật, và chính điều đó khiến tự do của bạn luôn có ý nghĩa.'),
('sagittarius', 'sun', 'en', 'A Sagittarius Sun lights an explorer''s fire in you that never quite goes out. You believe life is one grand adventure, and every new horizon carries a lesson worth learning. Your optimism is strangely contagious, pulling people out of their gloomiest days. You speak the truth and live it too, which is what gives your freedom its meaning.'),
('sagittarius', 'moon', 'vi', 'Mặt Trăng Nhân Mã cần không gian rộng để trái tim được thở. Khi buồn, bạn thường muốn đi đâu đó, học một điều mới, hoặc đơn giản là nhìn thấy bầu trời. Bạn xử lý cảm xúc bằng tiếng cười và những góc nhìn triết lý, biến nỗi đau thành bài học. Chỉ cần nhớ rằng đôi khi ở lại và đối diện cũng là một dạng phiêu lưu can đảm.'),
('sagittarius', 'moon', 'en', 'A Sagittarius Moon needs open space for the heart to breathe. When sadness comes, your instinct is to go somewhere, learn something new, or simply find a wide sky to look at. You process feelings through laughter and philosophy, turning pain into perspective. Just remember that staying and facing things can be its own brave kind of adventure.'),
('sagittarius', 'rising', 'vi', 'Cung Mọc Nhân Mã khiến bạn xuất hiện với nguồn năng lượng cởi mở và tinh thần lạc quan dễ mến. Người mới gặp thường ấn tượng bởi tiếng cười sảng khoái và những câu chuyện thú vị của bạn. Bạn khiến mọi người cảm thấy thế giới rộng lớn hơn chỉ sau một cuộc trò chuyện. Sự chân thành phóng khoáng ấy là tấm hộ chiếu đưa bạn đến với mọi trái tim.'),
('sagittarius', 'rising', 'en', 'Sagittarius rising makes you arrive with open energy and an easy, infectious optimism. New people are struck by your hearty laugh and the stories you seem to collect everywhere. After one conversation with you, the world somehow feels bigger. That candid, generous spirit is a passport that opens nearly every heart.'),

-- ============================================================ capricorn
('capricorn', 'sun', 'vi', 'Mặt Trời Ma Kết cho bạn ý chí của người leo núi: chậm rãi, bền bỉ và luôn hướng về đỉnh cao. Bạn không cần ồn ào để chứng minh bản thân; thành quả của bạn tự nói lên tất cả. Tinh thần trách nhiệm khiến bạn trở thành chỗ dựa vững chắc cho gia đình và đồng đội. Hãy nhớ tự thưởng cho mình trên từng chặng đường, vì hành trình cũng đáng quý như đích đến.'),
('capricorn', 'sun', 'en', 'A Capricorn Sun gives you the will of a mountain climber: patient, persistent, always moving toward the summit. You feel no need to be loud about your worth; your results speak clearly enough. Your sense of responsibility makes you the rock that family and colleagues lean on. Do remember to celebrate along the way, because the climb deserves joy as much as the peak does.'),
('capricorn', 'moon', 'vi', 'Mặt Trăng Ma Kết thường giữ cảm xúc sau một vẻ ngoài điềm tĩnh, tự nhắc mình phải mạnh mẽ trước đã. Bạn cảm thấy an toàn nhất khi cuộc sống ổn định và mọi thứ trong tầm kiểm soát. Tình cảm của bạn không ồn ào nhưng bền chắc như đá, thể hiện qua sự hiện diện đáng tin cậy mỗi ngày. Cho phép mình yếu lòng trước người mình tin tưởng không làm bạn nhỏ đi, mà khiến bạn trọn vẹn hơn.'),
('capricorn', 'moon', 'en', 'A Capricorn Moon tends to keep feelings behind a composed exterior, telling itself to be strong first and feel later. You are most at ease when life is stable and things are under control. Your love is quiet but solid as stone, shown through reliable presence day after day. Letting your guard down with people you trust does not make you smaller; it makes you whole.'),
('capricorn', 'rising', 'vi', 'Cung Mọc Ma Kết mang lại cho bạn phong thái chững chạc và đáng tin ngay từ ánh nhìn đầu tiên. Người mới gặp thường cảm nhận được sự nghiêm túc và năng lực của bạn, ngay cả khi bạn chưa nói gì nhiều. Bạn có thể hơi dè dặt ban đầu, nhưng theo thời gian, sự ấm áp và hài hước kín đáo của bạn dần lộ ra. Ấn tượng bạn để lại là của một người nói được, làm được.'),
('capricorn', 'rising', 'en', 'Capricorn rising gives you an air of maturity and quiet authority from the very first glance. New people sense your seriousness and competence before you have said much at all. You may seem reserved at first, but with time your warmth and dry humor slip through. The impression you leave is of someone whose word can be counted on.'),

-- ============================================================ aquarius
('aquarius', 'sun', 'vi', 'Mặt Trời Bảo Bình cho bạn một tâm trí đi trước thời đại và một trái tim hướng về cộng đồng. Bạn nhìn thế giới theo cách riêng, không ngại khác biệt, và thường là người đặt những câu hỏi mà chưa ai dám hỏi. Tự do tư tưởng với bạn quý hơn mọi sự công nhận. Chính sự độc đáo ấy giúp bạn mở ra những cánh cửa mà người khác còn chưa nhìn thấy.'),
('aquarius', 'sun', 'en', 'An Aquarius Sun gives you a mind that runs ahead of its time and a heart tuned to the collective. You see the world your own way, unafraid to be different, often asking the questions no one else dares to voice. Freedom of thought means more to you than any applause. That originality is exactly what lets you open doors others have not even noticed yet.'),
('aquarius', 'moon', 'vi', 'Mặt Trăng Bảo Bình thường quan sát cảm xúc từ một khoảng cách nhỏ, như nhà khoa học ngắm nhìn thí nghiệm của chính mình. Bạn cần không gian riêng ngay cả trong những mối quan hệ thân thiết nhất, và điều đó không có nghĩa là bạn yêu ít hơn. Bạn cảm thấy được thấu hiểu khi ai đó tôn trọng sự khác biệt của bạn thay vì cố thay đổi nó. Đôi khi, hãy để trái tim lên tiếng trước cả lý trí.'),
('aquarius', 'moon', 'en', 'An Aquarius Moon watches its own feelings from a small distance, like a scientist observing a fascinating experiment. You need breathing room even in your closest bonds, and that never means you love any less. You feel truly understood when someone respects your uniqueness instead of trying to edit it. Every now and then, let the heart speak before the head gets its turn.'),
('aquarius', 'rising', 'vi', 'Cung Mọc Bảo Bình khiến bạn toát ra một nét khác biệt thú vị mà người khác khó gọi tên. Người mới gặp thường thấy bạn thân thiện nhưng độc lập, dễ nói chuyện nhưng không dễ đoán. Bạn thu hút những tâm hồn cởi mở và những cuộc trò chuyện không giống ai. Chính sự nguyên bản ấy là dấu ấn khiến bạn nổi bật giữa đám đông.'),
('aquarius', 'rising', 'en', 'Aquarius rising gives you an intriguing originality that people can sense but rarely name. New acquaintances find you friendly yet independent, easy to talk to yet hard to predict. You naturally attract open minds and conversations unlike anyone else''s. That unmistakable authenticity is what makes you stand out in any crowd.'),

-- ============================================================ pisces
('pisces', 'sun', 'vi', 'Mặt Trời Song Ngư trao cho bạn trí tưởng tượng bao la và một lòng trắc ẩn hiếm có. Bạn cảm nhận được nỗi niềm của người khác như thể đó là của chính mình, và nghệ thuật hay những giấc mơ là ngôn ngữ tự nhiên của bạn. Thế giới cần sự dịu dàng của bạn nhiều hơn bạn nghĩ. Hãy giữ cho mình những ranh giới lành mạnh, để lòng tốt ấy được trao đi mà không cạn kiệt.'),
('pisces', 'sun', 'en', 'A Pisces Sun gives you a boundless imagination and a rare depth of compassion. You feel what others feel as if it were your own, and art and dreams are your native language. The world needs your gentleness more than you realize. Keep healthy boundaries around that kindness, so it can flow without ever running dry.'),
('pisces', 'moon', 'vi', 'Mặt Trăng Song Ngư khiến đời sống nội tâm của bạn mênh mông như đại dương: đầy trực giác, mộng mơ và những rung cảm tinh tế. Bạn hấp thụ cảm xúc của môi trường xung quanh, nên những khoảng lặng một mình là liều thuốc cần thiết. Âm nhạc, nghệ thuật hay thiên nhiên có thể chữa lành bạn nhanh hơn mọi lời khuyên. Trực giác của bạn là chiếc la bàn quý giá, hãy học cách tin vào nó.'),
('pisces', 'moon', 'en', 'A Pisces Moon makes your inner life as vast as the ocean: intuitive, dreamlike, exquisitely sensitive. You absorb the moods around you, which is why quiet time alone is genuine medicine for you. Music, art or a walk in nature can heal you faster than any advice. Your intuition is a precious compass; learn to trust where it points.'),
('pisces', 'rising', 'vi', 'Cung Mọc Song Ngư phủ lên bạn một vẻ mơ màng, dịu dàng khiến người khác thấy dễ mến ngay lập tức. Ánh mắt của bạn như biết lắng nghe, và người lạ cũng dễ dàng mở lòng với bạn. Bạn thích nghi với mọi hoàn cảnh một cách mềm mại, như nước tìm đường chảy. Ấn tượng bạn để lại là một sự ấm áp khó diễn tả nhưng rất khó quên.'),
('pisces', 'rising', 'en', 'Pisces rising wraps you in a soft, dreamlike quality that people warm to immediately. Your eyes seem to listen, and even strangers find themselves opening up to you. You adapt to any setting with a fluid grace, like water finding its way. The impression you leave is a warmth that is hard to describe and even harder to forget.');
